  `).join(""),re(t),be(t,".start-link[data-tab]"),e.querySelectorAll(".tm-toc-link").forEach(a=>{a.addEventListener("click",i=>{let o=document.querySelector(`.acc-card[data-id="${a.dataset.target}"]`);o&&!o.classList.contains("open")&&(i.preventDefault(),o.classList.add("open"),requestAnimationFrame(()=>o.scrollIntoView({behavior:"smooth",block:"start"})))})})}var cs=[{id:"all",label:"All"},{id:"ai",label:"AI & Security"},{id:"vuln",label:"Vulnerabilities"},{id:"ot",label:"OT / Industrial"},{id:"landscape",label:"Threat Landscape"}];async function Vr(e){e.innerHTML=`
